/// <summary>
/// pupulates data
/// </summary>
/// <param name = "_NDXSNSalesItemGroupCustomerTmp">NDXSNSalesItemGroupCustomerTmp reord</param>
/// <param name = "_signature">signature</param>
static void pupulateData(NDXSNSalesItemGroupCustomerTmp _NDXSNSalesItemGroupCustomerTmp, NDXSignature _signature)
{
    TaxValue taxValue1 = NDXSNParameters::find().showTaxValueTaxDate1();
    TaxValue taxValue2 = NDXSNParameters::find().showTaxValueTaxDate2();
    boolean gen2Records = taxValue1 != taxValue2;

    NDXSNExportDataMitegro lNDXSNExportDataMitegro;
    NDXSNSalesItemGroupCustomerTmp nDX_SNSalesItemGroupCustomerTmp;
    NDXSNSalesItemGroupCustomerTmp nDX_SNSalesItemGroupCustomerTmpGrp;

    int i;
    boolean lFirst = true;

    nDX_SNSalesItemGroupCustomerTmp.setTmpData(_NDXSNSalesItemGroupCustomerTmp);
    nDX_SNSalesItemGroupCustomerTmpGrp.setTmpData(_NDXSNSalesItemGroupCustomerTmp);

    while select sum(SalesAmount),sum(SalesAmountCum),sum(SalesAmountCumTaxValue1),sum(SalesAmountCumTaxValue2) from nDX_SNSalesItemGroupCustomerTmpGrp
        group by SalesYear, SalesMonth, ChildSalesNote
        where nDX_SNSalesItemGroupCustomerTmpGrp.Active
    {
        for (i=1; i<=(gen2Records?2:1); i++)
        {

            lNDXSNExportDataMitegro.SalesYear = nDX_SNSalesItemGroupCustomerTmpGrp.SalesYear;
            lNDXSNExportDataMitegro.SalesMonth = nDX_SNSalesItemGroupCustomerTmpGrp.SalesMonth;
            lNDXSNExportDataMitegro.Bonus = '0';
            lNDXSNExportDataMitegro.CustAccount = nDX_SNSalesItemGroupCustomerTmpGrp.ChildSalesNote ;
            lNDXSNExportDataMitegro.SalesAmount = decRound(i==1 ? nDX_SNSalesItemGroupCustomerTmpGrp.SalesAmountCumTaxValue1 : nDX_SNSalesItemGroupCustomerTmpGrp.SalesAmountCumTaxValue2,2);
            lNDXSNExportDataMitegro.VAT = decRound(i==1 ? taxValue1 : taxValue2,2);
            lNDXSNExportDataMitegro.Signature = _signature;
            lNDXSNExportDataMitegro.insert();
            lFirst = false;
        }

        while select nDX_SNSalesItemGroupCustomerTmp
            order by nDX_SNSalesItemGroupCustomerTmp.ArtGrpSalesNote
            where    nDX_SNSalesItemGroupCustomerTmp.ChildSalesNote == nDX_SNSalesItemGroupCustomerTmpGrp.ChildSalesNote
                &&   nDX_SNSalesItemGroupCustomerTmp.Active
        {
            for (i=1; i<=(gen2Records?2:1); i++)
            {
                lFirst  = true;
                lNDXSNExportDataMitegro.SalesYear = nDX_SNSalesItemGroupCustomerTmp.SalesYear;
                lNDXSNExportDataMitegro.SalesMonth = nDX_SNSalesItemGroupCustomerTmp.SalesMonth;
                lNDXSNExportDataMitegro.Bonus = nDX_SNSalesItemGroupCustomerTmp.ArtGrpSalesNote;
                lNDXSNExportDataMitegro.CustAccount = nDX_SNSalesItemGroupCustomerTmp.ChildSalesNote ;
                lNDXSNExportDataMitegro.SalesAmount = decRound(i==1 ? nDX_SNSalesItemGroupCustomerTmp.SalesAmountCumTaxValue1 : nDX_SNSalesItemGroupCustomerTmp.SalesAmountCumTaxValue2,2);
                lNDXSNExportDataMitegro.VAT = decRound(i==1 ? taxValue1 : taxValue2,2);
                lNDXSNExportDataMitegro.Signature = _signature;
                lNDXSNExportDataMitegro.insert();
                lFirst = false;

            }

        }
    }
}
